<?php $destination=match($layer){'organizations'=>'/organization','mentors'=>'/mentor/profile',default=>'/experience'};$detailUrl=$this->url($destination.'?id='.$row['id']);$image=$layer==='organizations'?($row['logo_asset_id']??null):($layer==='mentors'?($row['avatar_asset_id']??null):null); ?>
<article class="card atlas-result" data-detail-url="<?= $this->h($detailUrl) ?>"><a class="atlas-result-visual" href="<?= $this->h($detailUrl) ?>" aria-label="<?= $this->h($row['title']) ?>"><?php if($image): ?><img class="atlas-entity-image <?= $layer==='mentors'?'atlas-portrait':'atlas-logo' ?>" src="<?= $this->h($this->url('/content/asset?id='.$image)) ?>" width="80" height="80" alt="" loading="lazy" decoding="async"><?php else: ?><span class="service-icon"><?= $this->icon(match($layer){'organizations'=>'home','mentors'=>'user',default=>'book'}) ?></span><?php endif; ?></a><h3><a href="<?= $this->h($detailUrl) ?>"><?= $this->h($row['title']) ?></a></h3><?php if(!empty($row['province_name'])): ?><p class="small muted"><?= $this->icon('pin') ?><?= $this->h($row['province_name'].' · '.($row['county_name']??'شهرستان ثبت نشده')) ?></p><?php endif; ?><p class="atlas-result-summary"><?= $this->h($this->excerpt($row['summary']??'',190)) ?></p><?php if($layer!=='experiences'): ?><span class="tag"><?= $this->number($row['matched_experiences']) ?> تجربهٔ مرتبط با این انتخاب</span><?php if($layer==='organizations'): ?><span class="small muted atlas-result-stats"><?= $this->number($row['total_experiences']??0) ?> تجربه در کل · <?= $this->number($row['total_mentors']??0) ?> مرشد</span><?php endif; ?><?php elseif(!empty($row['display_name'])): ?><p class="small muted atlas-result-byline">مرشد: <?= $this->h($row['display_name']) ?></p><?php endif; ?><a class="primary atlas-result-action" href="<?= $this->h($detailUrl) ?>"><?= $layer==='experiences'?'خواندن تجربه':($layer==='organizations'?'شناخت مجموعه':'شناخت مرشد و گفت‌وگو') ?><?= $this->icon('arrow') ?></a></article>
